  onClose: () => void;
}

// Mở WebSocket; reject khi lỗi hoặc quá hạn timeoutMs
export function exConnect(url: string, timeoutMs: number): Promise<Transport> {
  return new Promise<Transport>((resolve, reject) => {
    let ws: WebSocket;
    try { ws = new WebSocket(url); } catch (e) { reject(e); return; }
    let opened = false;
    let handler: ((m: ServerMsg) => void) | null = null;
    const pending: ServerMsg[] = [];   // tin tới trước khi người dùng gán onMessage (máy chủ gửi lobby ngay khi nhận kết nối) được giữ lại, không mất
    const tm = setTimeout(() => { if (!opened) { try { ws.close(); } catch (e) { /* bỏ qua */ } reject(new Error('timeout')); } }, timeoutMs);
    const t: Transport = {
      send: m => { if (ws.readyState === 1) ws.send(JSON.stringify(m)); },
      close: () => { try { ws.close(); } catch (e) { /* bỏ qua */ } },
      get onMessage() { return handler as (m: ServerMsg) => void; },
      set onMessage(fn: (m: ServerMsg) => void) { handler = fn; while (pending.length) fn(pending.shift() as ServerMsg); },
      onClose: () => {}
    };
    ws.onopen = () => { opened = true; clearTimeout(tm); resolve(t); };
    ws.onmessage = ev => {
      let m: ServerMsg;
      try { m = JSON.parse(String(ev.data)); } catch (e) { return; }
      if (m && typeof m.t === 'string') { if (handler) handler(m); else pending.push(m); }
    };
    ws.onerror = () => { if (!opened) { clearTimeout(tm); reject(new Error('ws error')); } };
    ws.onclose = () => { clearTimeout(tm); if (!opened) reject(new Error('closed')); else t.onClose(); };
  });
}
/* ===== Dù lượn nhiều người: máy trạng thái phiên (không DOM, không three) ===== */
import type { Flyer, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  mySlot = -1;
  watched = -1;       // slot đang xem, -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n)) {}

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  join(name: string): void {
    this.name = name; this.notice = '';
    this.t?.send({ t: 'join', name });
  }

  // Rời chỗ bay (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
  leave(): void {
    if (this.phase !== 'flying') return;
    this.t?.send({ t: 'leave' });
    this.notice = 'released'; this.toWatching();
    this.onChange();
  }

  sendPos(x: number, y: number, z: number, yaw: number, bank: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank });
  }

  heartbeat(): void {
    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
  }

  dispose(): void {
    this.disposed = true;
    this.t?.close(); this.t = null;
  }

  private toWatching(): void {
    this.phase = 'watching'; this.mySlot = -1;
    this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
    this.fixWatched();
  }
  private mySlotWas = -1;

  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác
  private fixWatched(): void {
    const ids = this.flyers.map(f => f.slot);
    if (this.phase === 'watching') {
      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
      this.invite = ids.length < multiParams.slots;
    } else { this.watched = -1; this.invite = false; }
  }

  private lost(): void {
    if (this.disposed) return;
    this.phase = 'solo'; this.notice = 'lost';
    this.flyers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
    this.t = null; this.onChange();
  }

  private recv(m: ServerMsg): void {
    if (this.disposed) return;
    switch (m.t) {
      case 'lobby':
        this.flyers = m.flyers;
        if (this.first) {
          this.first = false;
          if (m.flyers.length >= multiParams.slots) this.phase = 'watching';
          else this.phase = 'lobby';
        }
        // đang bay: danh sách chỉ để hiển thị
        this.fixWatched();
        break;
      case 'joined':
        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
        this.fixWatched();
        break;
      case 'rejected':
        if (m.why === 'name') this.notice = 'nameBad';
        else {
          if (this.phase === 'watching') this.notice = 'late';
          else { this.phase = 'watching'; }
          this.fixWatched();
        }
        break;
      case 'pos':
        this.onPos(m.f);
        return;
      case 'released':
        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
        break;
    }
    this.onChange();
  }
}
/* ===== Dù lượn nhiều người: điều phối phía khách =====
   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), nhãn tên và danh sách người bay.
   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
import { camera } from '../../core/renderer';
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exConnect } from './client';
import { MultiSession } from './session';
import { exRemotes } from './remote';
import { exLabelsUpdate, exLabelsClear } from './labels';
import { ExIdle } from './idle';
import type { GliderState } from '../flight';

const M = CONFIG.explore.multi;
let session: MultiSession | null = null;
let sentAt = -1e9;
let rosterKey = '';
let idle: ExIdle | null = null;
let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi

/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
function idleParams(): [number, number] {
  const q = new URLSearchParams(location.search);
  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
}

function idleShow(text: string): void {
  const el = document.getElementById('exMpIdle');
  if (!el || text === idleShown) return;
  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
  idleShown = text;
  el.textContent = text;
  el.hidden = text === '';
}

function idleTick(): void {
  if (!session || !idle || session.phase !== 'flying') return;
  const now = performance.now();
  const st = idle.tick(now);
  if (st === 'ok') idleShow('');
  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
}

function idleStart(): void {
  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
  const [a, b] = idleParams();
  idle = new ExIdle(a, b); idle.reset(performance.now());
  idleShown = '';
  idleTimer = window.setInterval(idleTick, M.idleTickMs);
  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
}

function idleStop(): void {
  clearInterval(idleTimer); clearInterval(beatTimer);
  idleTimer = beatTimer = 0; idle = null;
  idleShow('');
}

/* Danh sách người bay ở góc màn hình: đầu "Đang bay n/5", mỗi người một dòng có chấm màu theo slot; dùng textContent */
function renderRoster(): void {
  const box = document.getElementById('exMpRoster');
  if (!box) return;
  const flyers = session ? session.flyers : [];
  const head = t('exMpFlying', { n: flyers.length });
  const key = flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + (session ? session.mySlot : -1) + '#' + head;
  if (key === rosterKey) return;
  rosterKey = key;
  box.hidden = !session || session.phase === 'solo';
  box.textContent = '';
  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
  for (const f of flyers) {
    const row = document.createElement('div'); row.className = 'ex-mp-row' + (session && f.slot === session.mySlot ? ' me' : '');
    const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
    const nm = document.createElement('span'); nm.textContent = f.name;
    row.append(dot, nm); box.appendChild(row);
  }
}

export const exMulti = {
  /* Địa chỉ máy chủ: ?multi= nếu có; ?test không có multi= thì rỗng (không mở mạng); còn lại cấu hình */
  url(): string {
    const q = new URLSearchParams(location.search);
    const u = q.get('multi');
    if (u !== null) return u;
    return q.has('test') ? '' : M.url;
  },
  get session(): MultiSession | null { return session; },
  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test

  /* Mở phiên; onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
  begin(onReady: () => void): boolean {
    const url = exMulti.url();
    if (!url || session) return false;
    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs));
    let ready = false;
    s.onPos = f => exRemotes.onPos(f, performance.now());
    s.onChange = () => {
      exRemotes.sync(s.flyers, s.mySlot);
      if (s.phase === 'solo') exLabelsClear();
      renderRoster();
      if (s.phase === 'flying') idleStart(); else idleStop();
      exMulti.onChange();
      if (!ready) { ready = true; onReady(); }
    };
    s.open();
    return true;
  },

  /* Mỗi khung khi đang bay: dù người khác, nhãn, gửi vị trí sendHz lần/s */
  update(_dt: number, nowMs: number, state: GliderState | null): void {
    if (!session) return;
    exRemotes.update(nowMs);
    exLabelsUpdate(camera, exRemotes, nowMs);
    if (state && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
      sentAt = nowMs;
      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank));
    }
  },

  /* Người bay vừa bấm phím điều khiển: đếm lại thời gian rời máy */
  activity(): void {
    if (!idle) return;
    idle.activity(performance.now());
    idleShow('');
  },

  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
  watchState(): GliderState | null {
    return session && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
  }
};

onLang(() => { rosterKey = ''; renderRoster(); });

