 99	import { t, onChange as onLang } from '../../i18n';
100	import { exSanitizeName } from './protocol';
101	import { exRemotes } from './remote';
102	import { loadName, saveName } from './lobby';
103	import type { MultiSession } from './session';
104	
105	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
106	
107	let session: MultiSession | null = null;
108	let bound = false;
109	let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
110	let pendingTimer = 0;
111	let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
112	let lateTimer = 0;
113	let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
114	let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)
115	
116	/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
117	const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
118	const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());
119	
120	/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
121	export function exWatchNotice(key: string): void {
122	  noticeKey = key;
123	  const el = $('exMpNotice');
124	  el.textContent = key ? t(key) : '';
125	  el.hidden = !key;
126	}
127	
128	function unlock(): void { pending = false; clearTimeout(pendingTimer); }
129	
130	function accept(): void {
131	  if (!session || session.phase !== 'watching' || pending) return;
132	  const input = $<HTMLInputElement>('exMpInviteName');
133	  const name = knownName() ?? exSanitizeName(input.value);
134	  if (name === null) return;
135	  pending = true; clearTimeout(pendingTimer);
136	  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
137	  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
138	  exWatchRender();
139	}
140	
141	export function exWatchRender(): void {
142	  const s = session;
143	  if (!s || s.phase !== 'watching') return;
144	  /* Dòng "Đang xem" */
145	  const nm = s.watched >= 0 ? exRemotes.name(s.watched) : null;
146	  const w = $('exMpWatch');
147	  w.hidden = nm === null;
148	  w.textContent = nm === null ? '' : t('exMpWatching', { name: '\u2068' + nm + '\u2069' });
149	  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
150	  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
151	    unlock();
152	    if (s.notice === 'late') { lateUntil = performance.now() + CONFIG.explore.multi.lateMs; clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50); }
153	  }
154	  if (s.notice === 'nameBad' && s.name !== rejected) {   // tên bị từ chối: quên tên đó (cả bản đã nhớ), hiện lại ô nhập để gõ tên khác
155	    rejected = s.name;
156	    if (exSanitizeName(loadName()) === rejected) saveName('');
157	    $<HTMLInputElement>('exMpInviteName').value = '';
158	  }
159	  let key = '';
160	  if (s.notice === 'late') key = performance.now() < lateUntil ? 'exMpLate' : '';
161	  else if (s.notice === 'released') key = 'exMpReleased';
162	  else if (s.notice === 'nameBad') key = 'exMpNameBad';
163	  exWatchNotice(key);
164	  /* Lời mời */
165	  const inv = $('exMpInvite'), input = $<HTMLInputElement>('exMpInviteName'), btn = $<HTMLButtonElement>('exMpInviteFly');
166	  inv.hidden = !s.invite;
167	  const needName = knownName() === null;
168	  input.hidden = !needName;
169	  btn.disabled = pending || (needName && exSanitizeName(input.value) === null);
170	}
