172	/* Bắt đầu hiện giao diện xem cho phiên s */
173	export function exWatchShow(s: MultiSession): void {
174	  session = s; unlock(); lateUntil = 0; rejected = null;
175	  if (!bound) {
176	    bound = true;
177	    $('exMpInviteFly').addEventListener('click', accept);
178	    const input = $<HTMLInputElement>('exMpInviteName');
