199	/* ===== Dù lượn nhiều người: đếm thời gian rời máy (không DOM, không timer; người gọi đưa mốc thời gian vào) =====
200	   Không chạm phím idleMs thì 'warn' (hỏi "Bạn còn đó không?"), thêm idleWarnMs nữa thì 'expired' (trả slot). */
201	export type IdleState = 'ok' | 'warn' | 'expired';
202	
203	export class ExIdle {
204	  private last = 0;   // ms — mốc phím cuối (hoặc mốc reset)
205	  constructor(private idleMs: number, private warnMs: number) {}
206	
207	  activity(now: number): void { this.last = now; }
208	  reset(now: number): void { this.last = now; }
209	
210	  tick(now: number): IdleState {
211	    const d = now - this.last;
212	    return d < this.idleMs ? 'ok' : d < this.idleMs + this.warnMs ? 'warn' : 'expired';
213	  }
214	
215	  /* Số giây còn lại tới lúc hết hạn, làm tròn lên (không âm) */
216	  remaining(now: number): number {
217	    return Math.max(0, Math.ceil((this.idleMs + this.warnMs - (now - this.last)) / 1000));
218	  }
219	}
220	/* ===== Dù lượn nhiều người: nhãn tên nổi dưới cánh dù người khác =====
221	   Một div cho mỗi slot trong #exMpLabels. Điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù), ẩn khi sau camera hoặc slot chưa hiện.
222	   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
223	import * as THREE from 'three';
224	import { CONFIG } from '../../config';
225	import type { exRemotes } from './remote';
226	
227	const M = CONFIG.explore.multi;
228	interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
229	let labs: Lab[] | null = null;
230	const _v = new THREE.Vector3();
231	
232	function init(): Lab[] | null {
233	  const box = document.getElementById('exMpLabels');
234	  if (!box) return null;
235	  return Array.from({ length: M.slots }, () => {
236	    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
237	    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
238	  });
239	}
240	
241	// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
242	const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
243	
244	export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number): void {
245	  if (!labs && !(labs = init())) return;
246	  const w = window.innerWidth, h = window.innerHeight;
247	  for (let i = 0; i < labs.length; i++) {
248	    const L = labs[i], st = remotes.slotState(i);
249	    let vis = false;
250	    if (st) {
251	      _v.set(st.pos.x, st.pos.y - M.labelBelow, st.pos.z).applyMatrix4(camera.matrixWorldInverse);
252	      if (-_v.z > 0.1) {   // trước camera
253	        _v.applyMatrix4(camera.projectionMatrix);
254	        const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
255	        if (px > -80 && px < w + 80 && py > -40 && py < h + 40) {
256	          vis = true;
257	          if (nowMs - L.tMs >= 200) {
258	            L.tMs = nowMs;
259	            const txt = `${remotes.name(i)} · ${dist(Math.hypot(st.pos.x - camera.position.x, st.pos.y - camera.position.y, st.pos.z - camera.position.z))}`;
260	            if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
261	          }
262	          if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
263	        }
264	      }
265	    }
266	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
267	  }
268	}
269	
270	/* Ẩn hết nhãn (rời phòng) */
271	export function exLabelsClear(): void {
272	  if (!labs) return;
273	  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
274	}

