    88	/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
    89	   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018). */
    90	const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
    91	export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
    92	
    93	export class ExTrack {
    94	  private buf = new Float64Array(N * W);
    95	  private head = 0;      // chỉ số ô sẽ ghi tiếp
    96	  private n = 0;         // số mẫu đang có
    97	  get count(): number { return this.n; }
    98	
    99	  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
   100	    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
   101	    const o = this.head * W, b = this.buf;
   102	    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
   103	    this.head = (this.head + 1) % N;
   104	    if (this.n < N) this.n++;
   105	  }
   106	
   107	  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu */
   108	  sample(t: number, out: ExPose): boolean {
   109	    if (this.n === 0) return false;
   110	    const b = this.buf, first = (this.head + N - this.n) % N * W;
   111	    const last = ((this.head + N - 1) % N) * W;
   112	    let a = first, c = first;
   113	    if (t >= b[last]) a = c = last;
   114	    else if (t > b[first]) {
   115	      for (let i = 0; i < this.n - 1; i++) {
   116	        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
   117	        if (t <= b[q]) { a = p; c = q; break; }
   118	      }
   119	    }
   120	    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
   121	    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
   122	    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
   123	    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
   124	    let dy = b[c + 4] - b[a + 4];
   125	    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
   126	    out.yaw = b[a + 4] + dy * k;
   127	    out.bank = b[a + 5] + (b[c + 5] - b[a + 5]) * k;
   128	    return true;
   129	  }
   130	
   131	  reset(): void { this.n = 0; this.head = 0; }
   132	}
