content.content:
1	     1	/* ===== Dù lượn nhiều người: dù của người bay cùng =====
2	     2	   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
3	     3	   Vị trí nhận 5 lần/s được nội suy, lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
4	     4	   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
5	     5	import * as THREE from 'three';
6	     6	import { scene } from '../../core/renderer';
7	     7	import { CONFIG } from '../../config';
8	     8	import { exBuildGlider, exPlaceGlider } from '../glider';
9	     9	import type { GliderState } from '../flight';
10	    10	import { ExTrack, type ExPose } from './interp';
11	    11	import type { Flyer } from './protocol';
12	    12	
13	    13	const M = CONFIG.explore.multi;
14	    14	
15	    15	interface RemoteSlot {
16	    16	  name: string | null;        // null = slot trống
17	    17	  group: THREE.Group | null;
18	    18	  track: ExTrack;
19	    19	  pose: ExPose;               // đệm lấy mẫu
20	    20	  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
21	    21	  live: boolean;              // đã có mẫu và đang hiện
22	    22	}
23	    23	
24	    24	const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
25	    25	  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
26	    26	  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
27	    27	}));
28	    28	let me = -1;
29	    29	
30	    30	function hide(s: RemoteSlot): void {
31	    31	  s.track.reset(); s.live = false;
32	    32	  if (s.group) s.group.visible = false;
33	    33	}
34	    34	
35	    35	export const exRemotes = {
36	    36	  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
37	    37	  sync(flyers: Flyer[], mySlot: number): void {
38	    38	    me = mySlot;
39	    39	    for (let i = 0; i < slots.length; i++) {
40	    40	      const s = slots[i];
41	    41	      let name: string | null = null;
42	    42	      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
43	    43	      if (name === null) { s.name = null; hide(s); continue; }
44	    44	      if (name !== s.name) {
45	    45	        s.name = name; hide(s);
