     1	/* ============================ Tự khám phá: màn chọn phương tiện ============================
     2	   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
     3	   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */
     4	
     5	import { getLang, onChange } from '../i18n';
     6	import { exMulti } from './multi';
     7	import { exShowLobby } from './multi/lobby';
     8	
     9	export type ExChoice = 'glider' | 'guided';
    10	
    11	const el = () => document.getElementById('chooser');
    12	
    13	/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
    14	function lockGliderOnTouch(root: HTMLElement): void {
    15	  if (!window.matchMedia('(hover: none)').matches) return;
    16	  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
    17	  if (!card) return;
    18	  card.disabled = true;
    19	  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
    20	}
    21	
    22	/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
    23	function wireLang(root: HTMLElement): void {
    24	  const mine = root.querySelector<HTMLSelectElement>('#exLang');
    25	  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
    26	  if (!mine || !main) return;
    27	  mine.innerHTML = main.innerHTML; mine.value = getLang();
    28	  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
    29	  onChange((code) => { mine.value = code; });
    30	}
    31	
    32	/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
    33	const inerted: HTMLElement[] = [];
    34	function setUnderInert(root: HTMLElement, on: boolean): void {
    35	  if (on) {
    36	    for (const c of Array.from(document.body.children) as HTMLElement[]) {
    37	      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
    38	      c.inert = true; inerted.push(c);
    39	    }
    40	  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
    41	}
    42	
    43	export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: () => void = () => {}): void {
    44	  const root = el();
    45	  if (!root) return;
    46	  lockGliderOnTouch(root);
    47	  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLost */
    48	  try { if (sessionStorage.getItem('exMpNotice') === 'lost') { sessionStorage.removeItem('exMpNotice'); const n = document.getElementById('exMpLostNote'); if (n) n.hidden = false; } } catch { /* bộ nhớ bị chặn */ }
    49	  wireLang(root);
    50	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
    51	    if (b.disabled) return;
    52	    b.addEventListener('click', () => {
    53	      const choice = b.dataset.pick as ExChoice;
    54	      /* Dù lượn có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay một mình ngay như trước */
    55	      if (choice === 'glider' && exMulti.begin(() => {})) {
    56	        const solo = () => { exHideChooser(); onPick('glider'); };
    57	        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(); }, onSolo: solo });
    58	        return;
    59	      }
    60	      exHideChooser(); onPick(choice);
    61	    }, { once: true });
    62	  });
    63	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
    64	  const loading = document.getElementById('loading');
    65	  if (!loading || loading.classList.contains('done')) { show(); return; }
    66	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
    67	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
    68	}
    69	
    70	export function exHideChooser(): void {
    71	  const root = el();
    72	  if (root) { root.hidden = true; setUnderInert(root, false); }
    73	}
